export interface Mark { readonly mark: true }
type Base<R> = { readonly base: R };
type Deco<R> = { [K in keyof R]: { use(): R[K] } };
// An intersection alias: the value prints expanded, the declared return names the alias.
export type HooksOf<R> = Base<R> & Deco<R>;
export declare function createHooks<R>(): HooksOf<R>;
